#!/bin/bash
set -euo pipefail
# Arguments are generated by deploy.py, never supplied by an external queue.
TASK_VOLUME_ID="$1"
TASK_BUNDLE_URI="$2"
TASK_BUNDLE_SHA="$3"
TASK_MOUNT=/opt/constellation
TASK_DEVICE=""
for candidate in /sys/block/nvme*n1/device/serial; do
    if [[ "$(tr -d '[:space:]' < "$candidate")" == "${TASK_VOLUME_ID//-/}" ]]; then
        TASK_NAME="${candidate#/sys/block/}"
        TASK_DEVICE="/dev/${TASK_NAME%%/*}"
    fi
done
[[ -n "$TASK_DEVICE" ]] || { echo 'Expected encrypted scratch volume not found'; exit 1; }
[[ "$(lsblk -dn -o TYPE "$TASK_DEVICE")" == disk ]] || exit 1
if ! blkid "$TASK_DEVICE" >/dev/null 2>&1; then
    # Refuse to format any disk with partitions or an existing filesystem.
    [[ "$(lsblk -nr -o NAME "$TASK_DEVICE" | wc -l)" == 1 ]] || exit 1
    mkfs.xfs "$TASK_DEVICE"
fi
mkdir -p "$TASK_MOUNT"
TASK_UUID="$(blkid -s UUID -o value "$TASK_DEVICE")"
if ! mountpoint -q "$TASK_MOUNT"; then
    mount "$TASK_DEVICE" "$TASK_MOUNT"
fi
[[ "$(findmnt -n -o UUID --target "$TASK_MOUNT")" == "$TASK_UUID" ]] || exit 1
if ! grep -Fq "UUID=$TASK_UUID " /etc/fstab; then
    echo "UUID=$TASK_UUID $TASK_MOUNT xfs defaults,nofail,nodev,nosuid 0 2" >> /etc/fstab
fi
dnf install -y python3.12 python3.12-pip
mkdir -p "$TASK_MOUNT/tmp"
aws s3 cp "$TASK_BUNDLE_URI" "$TASK_MOUNT/tmp/deploy.tar.gz" --region us-east-1 --only-show-errors
echo "$TASK_BUNDLE_SHA  $TASK_MOUNT/tmp/deploy.tar.gz" | sha256sum --check --status
# deploy.py builds an allowlisted archive containing code/configuration only.
tar -xzf "$TASK_MOUNT/tmp/deploy.tar.gz" -C "$TASK_MOUNT" --no-same-owner
python3.12 -m venv "$TASK_MOUNT/.venv"
"$TASK_MOUNT/.venv/bin/pip" install --disable-pip-version-check -r "$TASK_MOUNT/constellation/requirements.txt"
chown -R ec2-user:ec2-user "$TASK_MOUNT"
install -m 0644 "$TASK_MOUNT/constellation/constellation-backfill@.service" "$TASK_MOUNT/constellation/constellation-workers.slice" /etc/systemd/system/
systemctl daemon-reload
systemd-analyze verify /etc/systemd/system/constellation-backfill@.service
# Stage only: services are enabled after IAM and database permission checks.
echo 'constellation_worker_staged_collection_disabled'
